\documentclass[11pt]{amsart}
\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\theoremstyle{plain}
\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}
\newtheorem{remark}[theorem]{Remark}

\newcommand{\Inf}{\operatorname{Inf}}
\newcommand{\InfSub}{\operatorname{InfSub}}
\newcommand{\TotInf}{\operatorname{TotInf}}
\newcommand{\LinkTotInf}{\operatorname{LinkTotInf}}
\newcommand{\N}{\mathbb{N}}
\newcommand{\R}{\mathbb{R}}

\title{A Local-to-Global KKL Theorem for Partite Simplicial Complexes over an Arbitrary Alphabet}
\author{Aristotle}
\date{July 13, 2026}

\begin{document}
\begin{abstract}
We develop a local-to-global principle for coordinate influences of Boolean
labellings of the complete $n$-partite simplicial complex whose $n$ color classes
each contain $m$ vertices. The facets of this complex are the transversals
$x\colon\{1,\dots,n\}\to\{1,\dots,m\}$, and a labelling is a function $f$ from
transversals to $\{0,1\}$. We define the unnormalized influence $\Inf(f,i)$ of a
color $i$ as the number of sensitive $i$-edges---ordered pairs of transversals that
agree off coordinate $i$, differ at $i$, and receive different labels---and the link
influence $\InfSub(f,j,b,i)$ obtained by pinning color $j$ to vertex $b$. Our central
structural result is an exact self-averaging identity: for any fixed color $j$,
$\Inf(f,i)=\sum_{b} \InfSub(f,j,b,i)$. From this single equality we derive
monotonicity, a local-to-global decomposition of total influence, and the flagship
theorem that if all $m$ links of a color $j$ carry link-influence at least $T$, then
some color $i\neq j$ has global influence at least $mT/(n-1)$. We isolate the abstract
non-negative weighted-averaging engine, give the real-valued averaged form, and prove
an exact converse: a labelling all of whose color influences vanish is constant. The
Boolean hypercube is recovered as the case $m=2$, and the guaranteed global influence
grows linearly in the alphabet size $m$.
\end{abstract}

\maketitle

\section{Introduction}
The Kahn--Kalai--Linial (KKL) theorem is a cornerstone of the analysis of Boolean
functions: every balanced Boolean function on $n$ coordinates has a coordinate whose
influence is at least $\Omega(\log n / n)$, so influence cannot be spread perfectly
evenly and thinly. A more recent theme, driven by high-dimensional expanders, is the
\emph{local-to-global} paradigm: global properties of a simplicial complex are
deduced from the corresponding properties of its \emph{links}, the subcomplexes
obtained by fixing a face.

We carry out this program for coordinate influences on the complete $n$-partite
complex over an alphabet of size $m$, whose facets are the transversals and whose
links are obtained by pinning coordinates. The Boolean cube is the case $m=2$. Our
contribution is that in this setting the local-to-global transfer rests on an
\emph{exact} combinatorial identity, whose exactness reveals a linear dependence of
the guaranteed global influence on the alphabet size $m$ that approximate two-symbol
arguments cannot detect.

\section{The complex, its facets, and its links}
Fix integers $n\ge 1$ and $m\ge 1$. Write $[n]=\{1,\dots,n\}$ and $[m]=\{1,\dots,m\}$.

\begin{definition}[Complex and facets]
The complete $n$-partite simplicial complex over the alphabet $[m]$ has vertex set
$[n]\times[m]$, partitioned into $n$ color classes, the $i$-th being $\{i\}\times[m]$.
Its facets are the transversals: functions $x\colon[n]\to[m]$, identified with tuples
$(x_1,\dots,x_n)$; there are $m^n$ of them.
\end{definition}

\begin{definition}[Labelling]
A Boolean labelling is a function $f\colon([n]\to[m])\to\{0,1\}$.
\end{definition}

\begin{definition}[$i$-adjacency and sensitive edges]
Two facets $x,y$ are \emph{$i$-adjacent} if $x_k=y_k$ for all $k\neq i$ and
$x_i\neq y_i$. An $i$-adjacent ordered pair $(x,y)$ is \emph{sensitive} for $f$ if
additionally $f(x)\neq f(y)$.
\end{definition}

\begin{definition}[Influence]
The unnormalized influence of color $i$ is
\[
\Inf(f,i)=\#\{(x,y): (\forall k\neq i,\ x_k=y_k)\wedge x_i\neq y_i\wedge f(x)\neq f(y)\}.
\]
The total influence is $\TotInf(f)=\sum_{i\in[n]}\Inf(f,i)$.
\end{definition}

\begin{definition}[Link and link influence]
Fix a color $j$ and a vertex $b\in[m]$. The \emph{link of $(j,b)$} is the subcomplex
of facets $x$ with $x_j=b$. The link influence of color $i$ inside this link is
\[
\InfSub(f,j,b,i)=\#\{(x,y):(\forall k\neq i,\ x_k=y_k)\wedge x_i\neq y_i\wedge f(x)\neq f(y)\wedge x_j=b\},
\]
and the link total influence is $\LinkTotInf(f,j,b)=\sum_{i\neq j}\InfSub(f,j,b,i)$.
\end{definition}

\begin{remark}[Boolean cube]
When $m=2$, a facet is a bit-string in $\{0,1\}^n$, the $i$-adjacency graph is the
Hamming graph of the hypercube, and $\Inf(f,i)$ is the edge-boundary influence of
coordinate $i$. Each color has exactly two links.
\end{remark}

\section{The self-averaging bridge}
\begin{theorem}[Self-averaging bridge]\label{thm:bridge}
For every labelling $f$, every pinned color $j$, and every color $i$,
\[
\Inf(f,i)=\sum_{b\in[m]}\InfSub(f,j,b,i).
\]
\end{theorem}
\begin{proof}
Let $S$ be the set of sensitive $i$-adjacent ordered pairs $(x,y)$. Map each pair to
$x_j\in[m]$; this partitions $S$ into $m$ fibers. The fiber over $b$ is exactly the
set of sensitive $i$-adjacent pairs with $x_j=b$, i.e. the set counted by
$\InfSub(f,j,b,i)$. Since the cardinality of a finite set equals the sum of the
cardinalities of the fibers of any map on it, the identity follows.
\end{proof}

\begin{corollary}[Local bounds global]\label{cor:mono}
For all $j,b,i$, $\InfSub(f,j,b,i)\le\Inf(f,i)$.
\end{corollary}
\begin{proof}
Each summand in Theorem~\ref{thm:bridge} is a non-negative integer.
\end{proof}

\begin{corollary}[Local influential coordinate $\Rightarrow$ global]
If $\tau\le\InfSub(f,j,b,i)$ then $\tau\le\Inf(f,i)$.
\end{corollary}

\begin{theorem}[Local-to-global decomposition of total influence]\label{thm:linktot}
For every $f$ and $j$,
\[
\sum_{i\neq j}\Inf(f,i)=\sum_{b\in[m]}\LinkTotInf(f,j,b).
\]
\end{theorem}
\begin{proof}
Sum Theorem~\ref{thm:bridge} over $i\neq j$ and exchange the two finite sums.
\end{proof}

\section{From local guarantees to a global influential coordinate}
\begin{lemma}[Averaging pigeonhole]\label{lem:avg}
Let $S$ be a nonempty finite set and $g\colon S\to\N$. Then some $i\in S$ satisfies
$\sum_{s\in S}g(s)\le|S|\cdot g(i)$.
\end{lemma}
\begin{proof}
Choose $i$ maximizing $g$; then $\sum_s g(s)\le|S|\,g(i)$.
\end{proof}

\begin{theorem}[Local-to-global total-influence bound]\label{thm:total}
Fix a pinned color $j$ and $T\in\N$. If $T\le\LinkTotInf(f,j,b)$ for all $b\in[m]$,
then $m\cdot T\le\sum_{i\neq j}\Inf(f,i)$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:linktot} the right-hand side is
$\sum_b\LinkTotInf(f,j,b)\ge\sum_b T=mT$.
\end{proof}

\begin{theorem}[Local-to-Global KKL theorem, partite form]\label{thm:kkl}
Let $n\ge2$. Fix a pinned color $j$ and $T\in\N$ with $T\le\LinkTotInf(f,j,b)$ for
all $b\in[m]$. Then there exists a color $i\neq j$ with
\[
m\cdot T\le(n-1)\cdot\Inf(f,i),\qquad\text{i.e. }\Inf(f,i)\ge\frac{mT}{n-1}.
\]
\end{theorem}
\begin{proof}
The set $S=[n]\setminus\{j\}$ is nonempty with $|S|=n-1$. Apply
Lemma~\ref{lem:avg} to $g=\Inf(f,\cdot)$ on $S$ to get $i\neq j$ with
$\sum_{i'\neq j}\Inf(f,i')\le(n-1)\Inf(f,i)$; combine with Theorem~\ref{thm:total}.
\end{proof}

\begin{remark}[Alphabet-graded influence]
The guaranteed influence $mT/(n-1)$ grows linearly in $m$: enlarging the alphabet
multiplies the number of links, and by Theorem~\ref{thm:bridge} each link contributes
its full sensitive-edge count. When $m=2$ this scaling is invisible.
\end{remark}

\section{The abstract weighted-averaging engine}
\begin{theorem}[Abstract local-to-global bound]\label{thm:abs}
Let $B,C$ be finite, $a\colon B\times C\to\N$ non-negative with $G(c)=\sum_b a(b,c)$.
If $\sum_c a(b,c)\ge T$ for every $b\in B$, then $\sum_c G(c)\ge|B|\cdot T$.
\end{theorem}
\begin{proof}
$\sum_c G(c)=\sum_c\sum_b a(b,c)=\sum_b\sum_c a(b,c)\ge|B|\,T$.
\end{proof}

\begin{theorem}[Abstract global influential coordinate]
Under the hypotheses of Theorem~\ref{thm:abs} with $C$ nonempty, some $c\in C$
satisfies $|C|\cdot G(c)\ge|B|\cdot T$.
\end{theorem}
\begin{proof}
Combine Theorem~\ref{thm:abs} with Lemma~\ref{lem:avg}.
\end{proof}

\begin{theorem}[Real-valued averaged form]
With $n\ge2$, some color $i\neq j$ satisfies $\Inf(f,i)\ge mT/(n-1)$ in $\R$.
\end{theorem}
\begin{proof}
Divide the conclusion of Theorem~\ref{thm:kkl} by the positive integer $n-1$.
\end{proof}

\section{The exact degeneracy boundary}
\begin{theorem}[Zero influence forces constancy]\label{thm:const}
If $\Inf(f,i)=0$ for every color $i$, then $f$ is constant.
\end{theorem}
\begin{proof}
$\Inf(f,i)=0$ means $f$ is invariant under changing coordinate $i$. Any two facets are
connected by a path of single-coordinate flips, along each of which $f$ is constant;
hence $f$ is globally constant.
\end{proof}

\begin{corollary}[Degeneracy dichotomy]
A labelling is either globally degenerate (total influence zero, hence constant) or it
has a color with strictly positive influence; there is no intermediate regime.
\end{corollary}

\section{Applications and discussion}
For $m=2$ we recover a local-to-global statement for the Boolean cube: if both
sub-cubes $x_j=0$ and $x_j=1$ carry total influence at least $T$, some other
coordinate has influence at least $2T/(n-1)$. The partite complex realizes the
local-to-global paradigm by an exact identity rather than a spectral approximation,
and the abstract engine isolates exactly the ingredient the paradigm needs. In the
committee interpretation, the theorem says that if every candidate-restricted
electorate is collectively sensitive, some office is a genuine swing office.

\section{Future directions}
We conjecture an alphabet-graded influence gap (guaranteed global influence growing
linearly in $m$), a weighted non-regular link bound $\tau W$ with a sharp equality
case, a variance-thresholded degeneracy dichotomy, and a higher-codimension link
decomposition obtained by pinning two coordinates at once.

\end{document}

