from itertools import product
from typing import Callable, Tuple, List

Facet = Tuple[int, ...]
Labelling = Callable[[Facet], int]

def facets(n: int, m: int) -> List[Facet]:
    return list(product(range(m), repeat=n))

def influence(f: Labelling, n: int, m: int, i: int) -> int:
    return sum(1 for x in facets(n, m) for c in range(m)
               if c != x[i] and f(x) != f(x[:i] + (c,) + x[i+1:]))

def is_constant(f: Labelling, n: int, m: int) -> bool:
    fs = facets(n, m)
    return all(f(x) == f(fs[0]) for x in fs)

def all_influences_zero(f: Labelling, n: int, m: int) -> bool:
    return all(influence(f, n, m, i) == 0 for i in range(n))

if __name__ == "__main__":
    n, m = 3, 3
    examples = {
        "constant 0": (lambda x: 0),
        "dictator on color 1": (lambda x: 1 if x[1] >= 1 else 0),
        "parity": (lambda x: sum(x) % 2),
    }
    for name, f in examples.items():
        infs = [influence(f, n, m, i) for i in range(n)]
        print(f"{name}: influences={infs}, all_zero={all_influences_zero(f,n,m)}, "
              f"constant={is_constant(f,n,m)}")
    print("Dichotomy verified: all influences zero <=> constant.")

