"""Heatmap of link influences InfSub(f,j,b,i) across links b and colors i."""
from itertools import product
import matplotlib.pyplot as plt
import numpy as np

def influence_link(f, n, m, j, b, i):
    return sum(1 for x in product(range(m), repeat=n)
               if x[j] == b
               for c in range(m)
               if c != x[i] and f(x) != f(x[:i] + (c,) + x[i+1:]))

def main():
    n, m, j = 3, 4, 0
    f = lambda x: 1 if sum(x) % m == 0 else 0
    M = np.array([[influence_link(f, n, m, j, b, i) for i in range(n)]
                  for b in range(m)])
    plt.figure(figsize=(6, 4))
    plt.imshow(M, cmap="viridis", aspect="auto")
    plt.colorbar(label="InfSub(f, j, b, i)")
    plt.xlabel("color i"); plt.ylabel("link b (pinned color j=0)")
    plt.title("Link influences; each column sums to the global Inf(f,i)")
    for b in range(m):
        for i in range(n):
            plt.text(i, b, str(M[b, i]), ha="center", va="center", color="w")
    plt.tight_layout(); plt.savefig("link_influence_heatmap.png", dpi=150)
    print("Column sums (=Inf(f,i)):", M.sum(axis=0).tolist())

if __name__ == "__main__":
    main()

