from itertools import product
import matplotlib.pyplot as plt

def influence(f, n, m, i):
    return sum(1 for x in product(range(m), repeat=n) for c in range(m)
               if c != x[i] and f(x) != f(x[:i] + (c,) + x[i+1:]))

def link_total(f, n, m, j, b):
    return sum(1 for i in range(n) if i != j
               for x in product(range(m), repeat=n) if x[j] == b
               for c in range(m)
               if c != x[i] and f(x) != f(x[:i] + (c,) + x[i+1:]))

def main():
    n, j = 3, 0
    ms = list(range(2, 7))
    bound, actual = [], []
    for m in ms:
        f = lambda x, m=m: 1 if sum(x) % m == 0 else 0
        T = min(link_total(f, n, m, j, b) for b in range(m))
        bound.append(m * T / (n - 1))
        actual.append(max(influence(f, n, m, i) for i in range(n) if i != j))
    plt.figure(figsize=(6, 4))
    plt.plot(ms, bound, "o--", label="guaranteed bound m*T/(n-1)")
    plt.plot(ms, actual, "s-", label="max achieved Inf(f,i)")
    plt.xlabel("alphabet size m"); plt.ylabel("influence")
    plt.title(f"Alphabet-graded influence growth (n={n})")
    plt.legend(); plt.grid(True, alpha=0.3)
    plt.tight_layout(); plt.savefig("influence_growth.png", dpi=150)

if __name__ == "__main__":
    main()
